python3 -c '
import subprocess, json, shutil

browsers = {
    "google-chrome": ["google-chrome", "--version"],
    "chromium": ["chromium", "--version"],
    "firefox": ["firefox", "--version"],
    "safari": ["/usr/bin/osascript", "-e", "tell application \"Safari\" to version"]
}

target = "${answer1}".lower()
results = {}

if target in browsers:
    cmd = browsers[target]
    if shutil.which(cmd[0]) or cmd[0].startswith("/"):
        try:
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=5)
            results[target] = res.stdout.strip() or res.stderr.strip()
        except Exception as e:
            results[target] = f"Error: {str(e)}"
    else:
        results[target] = "Not installed"
else:
    for name, cmd in browsers.items():
        if shutil.which(cmd[0]) or cmd[0].startswith("/"):
            try:
                res = subprocess.run(cmd, capture_output=True, text=True, timeout=5)
                results[name] = res.stdout.strip() or res.stderr.strip()
            except Exception as e:
                results[name] = f"Error: {str(e)}"

print(json.dumps(results, indent=2))
'
